	if err != nil {
		if opts.requireAgent {
			return manifest, err
		}
		manifest.Deep = seedAgentPhase{Status: "skipped", Timeout: opts.agentDeepTimeout.String()}
		return manifest, err
	}
	deepInput, err := buildAgentInput("deep", repoDir, scan, quickArtifacts, opts)
	if err != nil {
		return manifest, err
	}
