func semanticBoundaryFacts(brainDir string, source *semanticSourceManifest, spec semanticBoundarySpec, limit int) (semanticBoundaryResult, error) {
	symbolsByID, relations, err := loadSemanticBoundaryRecords(brainDir, source, spec.RelationTypes)
	if err != nil {
		return semanticBoundaryResult{}, err
	}
	kindSet := lowerSet(spec.SymbolKinds)
	var result semanticBoundaryResult
	seenBoundaries := map[string]struct{}{}
	seenHandlers := map[string]struct{}{}

	addBoundary := func(record semanticRecord) {
		if _, seen := seenBoundaries[record.ID]; seen {
			return
		}
		if len(result.Boundaries) >= limit {
			return
		}
		seenBoundaries[record.ID] = struct{}{}
		result.Boundaries = append(result.Boundaries, record)
	}

	// boundaryFor reports whether an endpoint id is a boundary: either a
	// kind-tagged in-repo symbol or an external:<kind>:* node matching the spec.
	boundaryFor := func(id string) (semanticRecord, bool) {
		if symbol, ok := symbolsByID[id]; ok && semanticKindInSet(symbol.Kind, kindSet) {
			return symbol, true
		}
		return externalBoundaryRecord(id, kindSet)
	}

	// Boundaries emitted as in-repo symbols are listed even without a handler.
	for _, symbol := range sortedSemanticSymbols(symbolsByID) {
		if semanticKindInSet(symbol.Kind, kindSet) {
			addBoundary(symbol)
		}
	}

	for _, relation := range relations {
		fromBoundary, fromIsBoundary := boundaryFor(relation.FromID)
		toBoundary, toIsBoundary := boundaryFor(relation.ToID)
		if !fromIsBoundary && !toIsBoundary {
			continue
		}
		result.Relations = append(result.Relations, relation)
		for _, endpoint := range []struct {
			id         string
			boundary   semanticRecord
			isBoundary bool
		}{
			{relation.FromID, fromBoundary, fromIsBoundary},
			{relation.ToID, toBoundary, toIsBoundary},
		} {
			if endpoint.isBoundary {
				addBoundary(endpoint.boundary)
				continue
			}
			// The non-boundary endpoint is the handler, but only when it is a
			// real indexed symbol (external import nodes etc. are ignored).
			symbol, ok := symbolsByID[endpoint.id]
			if !ok {
				continue
			}
			if _, seen := seenHandlers[endpoint.id]; seen {
				continue
			}
			seenHandlers[endpoint.id] = struct{}{}
			result.Handlers = append(result.Handlers, symbol)
		}
	}
	return result, nil
}

