			return
		}
		if _, ok := seenCandidate[record.ID]; ok {
			return
		}
		seenCandidate[record.ID] = struct{}{}
		candidates = append(candidates, record)
	}
	for _, symbol := range sortedSemanticSymbols(symbolsByID) {
		if semanticKindInSet(symbol.Kind, kindSet) {
			addCandidate(symbol)
		}
	}
