package cli

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"reflect"
	"regexp"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

type Options struct {
	Version string
	Env     EntireEnv
	Runner  CommandRunner
	Now     func() time.Time
}

// Execute runs the plugin root command with the real process environment.
func Execute(version string) error {
	cmd := NewRootCommand(Options{
		Version: version,
		Env:     EnvFromOS(),
	})
	err := cmd.Execute()
	if err != nil && commandErrorWasRendered(err) {
		return err
	}
	return err
}

func NewRootCommand(opts Options) *cobra.Command {
	if opts.Version == "" {
		opts.Version = "dev"
	}
	if opts.Runner == nil {
		opts.Runner = ExecRunner{}
	}
	if opts.Now == nil {
		opts.Now = time.Now
	}

	cmd := &cobra.Command{
		Use:           "entire-brain",
		Short:         "Export Entire session history for agent review",
		SilenceUsage:  true,
		SilenceErrors: true,
		Long: `entire-brain is an external-command plugin for the Entire CLI.

It exports checkpointed session transcripts and metadata into a directory an
agent can inspect to understand project history.`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return cmd.Help()
		},
	}

	cmd.AddGroup(
		&cobra.Group{ID: "core", Title: "Core workflow:"},
		&cobra.Group{ID: "explore", Title: "Explore the brain:"},
		&cobra.Group{ID: "build", Title: "Build the brain:"},
		&cobra.Group{ID: "maintain", Title: "Maintain & share:"},
	)

	addGrouped := func(group string, c *cobra.Command) {
		c.GroupID = group
		cmd.AddCommand(c)
	}
	// addPluginInterface registers commands the Entire CLI host or MCP clients
	// invoke programmatically — never typed by a human for direct value. They
	// stay functional but are hidden from help to keep the surface task-focused.
	addPluginInterface := func(c *cobra.Command) {
		c.Hidden = true
		cmd.AddCommand(c)
	}

	// Core workflow — the everyday surface (mirrors `entire brain guide`).
	addGrouped("core", newRefreshCommand(opts))
	addGrouped("core", newAgentStatusCommand(opts))
	addGrouped("core", newBrainBriefCommand(opts))
	addGrouped("core", newBrainSearchCommand(opts))
	addGrouped("core", newBrainShowCommand(opts))
	addGrouped("core", newPathCommand(opts))
	addGrouped("core", newBrainGuideCommand())

	// Explore — query semantic facts, boundaries, and history.
	addGrouped("explore", newBrainInspectCommand(opts))
	addGrouped("explore", newSemanticContextCommand(opts))
	addGrouped("explore", newSemanticImpactCommand(opts))
	addGrouped("explore", newSemanticChangesCommand(opts))
	addGrouped("explore", newSemanticRoutesCommand(opts))
	addGrouped("explore", newSemanticToolsCommand(opts))
	addGrouped("explore", newSemanticWorkflowsCommand(opts))
	addGrouped("explore", newSemanticTestsCommand(opts))
	addGrouped("explore", newSemanticQueryCommand(opts))

	// Build — produce the brain from sessions, seed docs, and the provider.
	addGrouped("build", newSemanticIndexCommand(opts))
	addGrouped("build", newSeedCommand(opts))
	addGrouped("build", newExportCommand(opts))
	addGrouped("build", newHistoryIndexCommand(opts))

	// Maintain & share — health, cleanup, portability, multi-repo, config.
	addGrouped("maintain", newSemanticStaleCommand(opts))
	addGrouped("maintain", newSemanticRepairCommand(opts))
	addGrouped("maintain", newSemanticResetCommand(opts))
	addGrouped("maintain", newSemanticGCCommand(opts))
	addGrouped("maintain", newSemanticBundleCommand(opts))
	addGrouped("maintain", newWorkspaceCommand(opts))
	addGrouped("maintain", newDoctorCommand(opts))
	addGrouped("maintain", newConfigCommand(opts.Env))

	addPluginInterface(newMCPCommand(opts))
	addPluginInterface(newVersionCommand(opts.Version))

	cmd.SetHelpCommandGroupID("maintain")
	cmd.SetCompletionCommandGroupID("maintain")

	wrapJSONErrorRendering(cmd)
	return cmd
}

type commandJSONError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

type renderedCommandError struct {
	err error
}

var errRenderedCommand = renderedCommandError{}

func RenderedError() error {
	return errRenderedCommand
}

func (e renderedCommandError) Error() string {
	if e.err == nil {
		return "command error rendered"
	}
	return e.err.Error()
}

func (e renderedCommandError) Unwrap() error {
	return e.err
}

func (e renderedCommandError) Is(target error) bool {
	_, ok := target.(renderedCommandError)
	return ok
}

func commandErrorWasRendered(err error) bool {
	_, ok := err.(renderedCommandError)
	return ok
}

func wrapJSONErrorRendering(cmd *cobra.Command) {
	if cmd.Args != nil {
		argsFunc := cmd.Args
		cmd.Args = func(cmd *cobra.Command, args []string) error {
			err := argsFunc(cmd, args)
			if err == nil || !commandWantsJSONError(cmd) {
				return err
			}
			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
			return renderedCommandError{err: err}
		}
	}
	if cmd.RunE != nil {
		run := cmd.RunE
		cmd.RunE = func(cmd *cobra.Command, args []string) error {
			err := run(cmd, args)
			if err == nil || !commandWantsJSONError(cmd) {
				return err
			}
			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
			return renderedCommandError{err: err}
		}
	}
	cmd.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
		if !commandWantsJSONError(cmd) {
			return err
		}
		_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
		return renderedCommandError{err: err}
	})
	for _, child := range cmd.Commands() {
		wrapJSONErrorRendering(child)
	}
}

func commandWantsJSONError(cmd *cobra.Command) bool {
	if flag := cmd.Flags().Lookup("json"); flag != nil && flag.Changed {
		return commandJSONFlagEnabled(flag.Value.String())
	}
	if flag := cmd.InheritedFlags().Lookup("json"); flag != nil && flag.Changed {
		return commandJSONFlagEnabled(flag.Value.String())
	}
	for _, arg := range append(cmd.Flags().Args(), commandRawArgs(cmd)...) {
		if arg == "--json" {
			return true
		}
		if strings.HasPrefix(arg, "--json=") {
			value := strings.TrimPrefix(arg, "--json=")
			return value == "" || value == "true" || value == "1"
		}
	}
	return false
}

func commandJSONFlagEnabled(value string) bool {
	value = strings.ToLower(value)
	return value != "false" && value != "0"
}

func commandRawArgs(cmd *cobra.Command) []string {
	root := cmd.Root()
	if root == nil {
		return os.Args[1:]
	}
	value := reflect.ValueOf(root)
	if value.Kind() != reflect.Pointer || value.IsNil() {
		return os.Args[1:]
	}
	args := value.Elem().FieldByName("args")
	if !args.IsValid() || args.Kind() != reflect.Slice || args.IsNil() {
		return os.Args[1:]
	}
	out := make([]string, 0, args.Len())
	for i := 0; i < args.Len(); i++ {
		out = append(out, args.Index(i).String())
	}
	return out
}

var commandErrorCodePattern = regexp.MustCompile(`^[a-z][a-z0-9_-]*$`)

func writeCommandJSONError(w io.Writer, err error) error {
	envelope := commandJSONError{
		Code:    commandErrorCode(err),
		Message: err.Error(),
	}
	data, marshalErr := json.MarshalIndent(envelope, "", "  ")
	if marshalErr != nil {
		return marshalErr
	}
	_, writeErr := fmt.Fprintln(w, string(data))
	return writeErr
}

func commandErrorCode(err error) string {
	message := err.Error()
	code, _, ok := strings.Cut(message, ":")
	if ok {
		code = strings.TrimSpace(code)
		if commandErrorCodePattern.MatchString(code) {
			return code
		}
	}
	return "command_failed"
}

